import pptx

path = "/Data2/v-weilinjin/workshop/AttributeBench/benchmarks/GAIA/2023/validation/a3fbeb63-0e8c-4a11-bff6-0e3b484c3e9c.pptx"

def extract_text(path):
    prs = pptx.Presentation(path)
    out = []
    for idx, slide in enumerate(prs.slides, start=1):
        parts = []
        for shape in slide.shapes:
            if getattr(shape, "has_text_frame", False):
                parts.append(shape.text)
            elif hasattr(shape, "text"):
                parts.append(shape.text)
        out.append((idx, " ".join([p.strip() for p in parts if p and p.strip()])))
    return out

for num, txt in extract_text(path):
    print(f"Slide {num}: {txt}\n")
